/* ==========================================================================
   HUD tokens — steel (default) · teal · thermal · day
   Body text meets WCAG AA (≥ 4.5:1) on panel fills in every palette.
   ========================================================================== */

:root {
  color-scheme: dark;

  /* ---- Steel (default) ------------------------------------------------- */
  --paper: #06090d;
  --sheet: rgba(14, 22, 30, 0.8);
  --sheet-solid: #0e161e;
  --soft: rgba(19, 30, 41, 0.88);
  --line: #26394b;
  --ink: #c3d0da;
  --muted: #8499ab;

  --accent: #7fa7c4;
  --accent-d: #4d738f;
  --on-accent: #060b10;

  --ok: #7cc79a;
  --ok-d: #468e63;
  --ok-bg: rgba(124, 199, 154, 0.14);
  --on-ok: #05130b;

  --bad: #d8616c;
  --bad-d: #96363f;
  --bad-bg: rgba(216, 97, 108, 0.15);
  --on-bad: #160507;

  --mark: #d6b26a;
  --mark-d: #9c7c3a;
  --mark-ink: #1a1204;

  --glow-color: rgba(127, 167, 196, 0.35);
  --grid-color: rgba(127, 167, 196, 0.055);

  --scrim: rgba(3, 6, 10, 0.78);
  --shadow-soft: rgba(0, 0, 0, 0.48);
  --shadow-pop: rgba(0, 0, 0, 0.65);
  --thumb-hover-mix: #ffffff;

  /* ---- Typography ------------------------------------------------------ */
  --hud-font-display: 'Chakra Petch', 'Be Vietnam Pro', system-ui, sans-serif;
  --hud-font-body: 'Be Vietnam Pro', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --hud-font-mono: 'JetBrains Mono', ui-monospace, Menlo, monospace;
  --hud-font-label: var(--hud-font-mono);

  --f-display: var(--hud-font-display);
  --f-body: var(--hud-font-body);
  --f-mono: var(--hud-font-mono);
  --f-label: var(--hud-font-label);

  /* ---- Spacing --------------------------------------------------------- */
  --hud-space-1: 4px;
  --hud-space-2: 8px;
  --hud-space-3: 12px;
  --hud-space-4: 16px;
  --hud-space-5: 20px;
  --hud-space-6: 24px;

  /* ---- Chamfer --------------------------------------------------------- */
  --hud-chamfer: 10px;
  --hud-chamfer-sm: 6px;
  --hud-chamfer-lg: 14px;
  --hud-chamfer-polygon: polygon(
    0 var(--hud-chamfer),
    var(--hud-chamfer) 0,
    calc(100% - var(--hud-chamfer)) 0,
    100% var(--hud-chamfer),
    100% calc(100% - var(--hud-chamfer)),
    calc(100% - var(--hud-chamfer)) 100%,
    var(--hud-chamfer) 100%,
    0 calc(100% - var(--hud-chamfer))
  );

  /* ---- Motion ---------------------------------------------------------- */
  --hud-duration-fast: 160ms;
  --hud-duration: 280ms;
  --hud-duration-slow: 480ms;
  --hud-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
}

:root[data-hud-palette='teal'] {
  --paper: #050b0b;
  --sheet: rgba(10, 24, 23, 0.8);
  --sheet-solid: #0a1817;
  --soft: rgba(14, 33, 31, 0.88);
  --line: #1f3f3c;
  --ink: #bfd6d0;
  --muted: #799c96;

  --accent: #6fb5a6;
  --accent-d: #447e72;
  --on-accent: #04110f;

  --ok: #9ccf6e;
  --ok-d: #5e8c36;
  --ok-bg: rgba(156, 207, 110, 0.14);
  --on-ok: #091304;

  --bad: #d9675e;
  --bad-d: #963b34;
  --bad-bg: rgba(217, 103, 94, 0.15);

  --mark: #d8b56a;
  --mark-d: #997b38;
  --mark-ink: #1a1204;

  --glow-color: rgba(111, 181, 166, 0.35);
  --grid-color: rgba(111, 181, 166, 0.055);
}

:root[data-hud-palette='thermal'] {
  --paper: #0d0804;
  --sheet: rgba(28, 17, 7, 0.84);
  --sheet-solid: #1c1107;
  --soft: rgba(39, 24, 10, 0.9);
  --line: #5a3a14;
  --ink: #ffd9a0;
  --muted: #b89054;

  --accent: #ffa526;
  --accent-d: #b56c08;
  --on-accent: #1a0e02;

  --ok: #b5d46a;
  --ok-d: #738f31;
  --ok-bg: rgba(181, 212, 106, 0.15);
  --on-ok: #101603;

  --bad: #ff4d2e;
  --bad-d: #a82712;
  --bad-bg: rgba(255, 77, 46, 0.16);

  --mark: #ffd23f;
  --mark-d: #b38b0e;
  --mark-ink: #1f1400;

  --glow-color: rgba(255, 165, 38, 0.45);
  --grid-color: rgba(255, 165, 38, 0.065);
}

:root[data-hud-palette='day'] {
  color-scheme: light;

  --paper: #e8edf1;
  --sheet: rgba(255, 255, 255, 0.86);
  --sheet-solid: #f7f9fb;
  --soft: rgba(240, 245, 249, 0.94);
  --line: #a9bccb;
  --ink: #14222d;
  --muted: #4f6475;

  --accent: #2b668e;
  --accent-d: #1d4968;
  --on-accent: #ffffff;

  --ok: #1a6e41;
  --ok-d: #124d2d;
  --ok-bg: rgba(26, 110, 65, 0.11);
  --on-ok: #ffffff;

  --bad: #b02c36;
  --bad-d: #821d25;
  --bad-bg: rgba(176, 44, 54, 0.1);
  --on-bad: #ffffff;

  --mark: #7d5409;
  --mark-d: #5c3d05;
  --mark-ink: #ffffff;

  --glow-color: rgba(43, 102, 142, 0.28);
  --grid-color: rgba(43, 102, 142, 0.085);

  --scrim: rgba(232, 237, 241, 0.72);
  --shadow-soft: rgba(20, 34, 45, 0.14);
  --shadow-pop: rgba(20, 34, 45, 0.22);
  --thumb-hover-mix: #14222d;
}

:root[data-hud-grid='on'] body {
  background-color: var(--paper);
  background-image:
    linear-gradient(var(--grid-color) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-color) 1px, transparent 1px);
  background-size: 32px 32px;
}

/* ==========================================================================
   HUD chrome — chamfer, glow, scrollbars, boot motion
   Complements Tailwind utilities on components. Glow accents only;
   day palette uses crisp outlines (no blur glow).
   ========================================================================== */

body {
  background-color: var(--paper);
  color: var(--ink);
  font-family: var(--hud-font-body);
  font-size: 15.5px;
  line-height: 1.5;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 0;
}

/* ---- Dialog ------------------------------------------------------------ */

[data-hud-dialog-overlay] {
  transition: opacity var(--hud-duration) var(--hud-ease);
}

[data-hud-dialog-overlay][data-state='closed'] {
  opacity: 0;
  pointer-events: none;
}

[data-hud-dialog] {
  clip-path: var(--hud-chamfer-polygon);
  translate: 0 0;
  opacity: 1;
  transition:
    opacity var(--hud-duration) var(--hud-ease),
    translate var(--hud-duration) var(--hud-ease),
    clip-path var(--hud-duration) var(--hud-ease);
}

[data-hud-dialog][data-state='closed'] {
  opacity: 0;
  translate: 0 8px;
}

[data-hud-dialog-title].hud-glow-title {
  color: var(--accent);
  text-shadow:
    0 0 8px var(--glow-color),
    0 0 2px var(--glow-color);
}

:root[data-hud-glow='on'] [data-hud-dialog-title] {
  color: var(--accent);
  text-shadow:
    0 0 8px var(--glow-color),
    0 0 2px var(--glow-color);
}

:root[data-hud-palette='day'][data-hud-glow='on'] [data-hud-dialog-title] {
  text-shadow: none;
  color: var(--accent-d);
}

:root[data-hud-glow='off'] [data-hud-dialog-title] {
  text-shadow: none;
}

/* ---- Corner brackets --------------------------------------------------- */

[data-hud-corner-brackets] {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

[data-hud-corner-brackets]::before,
[data-hud-corner-brackets]::after {
  content: '';
  position: absolute;
  width: 14px;
  height: 14px;
  border: 0 solid var(--accent);
  border-width: 2px;
}

[data-hud-corner-brackets]::before {
  top: 4px;
  left: 4px;
  border-right: 0;
  border-bottom: 0;
}

[data-hud-corner-brackets]::after {
  bottom: 4px;
  right: 4px;
  border-left: 0;
  border-top: 0;
}

/* ---- Tabs / Toggle shared accent glow ---------------------------------- */

:root[data-hud-glow='on'] [data-hud-tab][data-selected='true'],
:root[data-hud-glow='on'] [data-hud-toggle][data-pressed='true'] {
  box-shadow:
    inset 0 0 18px -10px var(--glow-color),
    0 0 10px -4px var(--glow-color);
}

:root[data-hud-palette='day'][data-hud-glow='on'] [data-hud-tab][data-selected='true'],
:root[data-hud-palette='day'][data-hud-glow='on'] [data-hud-toggle][data-pressed='true'] {
  box-shadow: none;
}

[data-hud-tab],
[data-hud-toggle] {
  clip-path: var(--hud-chamfer-polygon);
  transition:
    color var(--hud-duration-fast) var(--hud-ease),
    background-color var(--hud-duration-fast) var(--hud-ease),
    border-color var(--hud-duration-fast) var(--hud-ease);
}

/* ---- Meter ------------------------------------------------------------- */

[data-hud-meter-track] {
  clip-path: polygon(0 0, 100% 0, calc(100% - 4px) 100%, 4px 100%);
}

[data-hud-meter][data-variant='segments'] [data-hud-meter-track],
[data-hud-meter][data-variant='ring'] [data-hud-meter-track] {
  clip-path: none;
}

[data-hud-meter-fill] {
  width: var(--hud-meter-pct, 0%);
  transition: width var(--hud-duration) var(--hud-ease);
}

:root[data-hud-glow='on'] [data-hud-meter-fill] {
  box-shadow: 0 0 10px var(--glow-color);
}

:root[data-hud-palette='day'][data-hud-glow='on'] [data-hud-meter-fill] {
  box-shadow: none;
}

[data-hud-meter-segment] {
  clip-path: polygon(0 0, 100% 0, calc(100% - 3px) 100%, 3px 100%);
}

:root[data-hud-glow='on'] [data-hud-meter-segment][data-on='true'] {
  box-shadow: 0 0 6px var(--glow-color);
}

:root[data-hud-palette='day'][data-hud-glow='on'] [data-hud-meter-segment][data-on='true'] {
  box-shadow: none;
}

[data-hud-meter-ring] circle[data-role='track'] {
  stroke: var(--line);
  stroke-width: 4;
}

[data-hud-meter-ring] circle[data-role='fill'] {
  stroke: var(--accent);
  stroke-width: 4;
  transition: stroke-dashoffset var(--hud-duration) var(--hud-ease);
}

:root[data-hud-glow='on'] [data-hud-meter-ring] circle[data-role='fill'] {
  filter: drop-shadow(0 0 4px var(--glow-color));
}

:root[data-hud-palette='day'][data-hud-glow='on'] [data-hud-meter-ring] circle[data-role='fill'] {
  filter: none;
}

/* ---- TextScramble ------------------------------------------------------- */

[data-hud-text-scramble][data-phase='running'] {
  color: var(--accent);
}

/* ---- ScrollPanel ------------------------------------------------------- */

[data-hud-scroll-panel] {
  clip-path: polygon(
    0 0,
    calc(100% - 12px) 0,
    100% 12px,
    100% 100%,
    12px 100%,
    0 calc(100% - 12px)
  );
}

[data-hud-scroll-panel]::before,
[data-hud-scroll-panel]::after {
  content: '';
  position: absolute;
  width: 10px;
  height: 10px;
  border-color: var(--accent);
  border-style: solid;
  pointer-events: none;
  z-index: 3;
}

[data-hud-scroll-panel]::before {
  top: 4px;
  left: 4px;
  border-width: 2px 0 0 2px;
}

[data-hud-scroll-panel]::after {
  bottom: 4px;
  right: 4px;
  border-width: 0 2px 2px 0;
}

[data-hud-scroll-panel-body] {
  --fade-top: 0px;
  --fade-bot: 0px;
  scrollbar-width: thin;
  scrollbar-color: var(--accent) transparent;
}

[data-hud-scroll-panel-body][data-scrollable='true'] {
  --fade-top: 24px;
  --fade-bot: 24px;
  mask-image: linear-gradient(
    to bottom,
    transparent,
    #000 var(--fade-top),
    #000 calc(100% - var(--fade-bot)),
    transparent
  );
}

[data-hud-scroll-panel-body][data-at-top='true'] {
  --fade-top: 0px;
}

[data-hud-scroll-panel-body][data-at-bottom='true'] {
  --fade-bot: 0px;
}

[data-hud-scroll-panel-body]::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

[data-hud-scroll-panel-body]::-webkit-scrollbar-button {
  display: none;
  width: 0;
  height: 0;
}

[data-hud-scroll-panel-body]::-webkit-scrollbar-track {
  background:
    linear-gradient(
      to right,
      transparent 2px,
      color-mix(in srgb, var(--line) 75%, transparent) 2px,
      color-mix(in srgb, var(--line) 75%, transparent) 4px,
      transparent 4px
    ),
    repeating-linear-gradient(to bottom, var(--accent) 0 1px, transparent 1px 10%);
}

[data-hud-scroll-panel-body]::-webkit-scrollbar-thumb {
  background: linear-gradient(
    135deg,
    transparent 3px,
    var(--accent) 3px,
    var(--accent) calc(100% - 3px),
    transparent calc(100% - 3px)
  );
  border-radius: 0;
}

:root[data-hud-glow='on'] [data-hud-scroll-panel-body]::-webkit-scrollbar-thumb:hover,
:root[data-hud-glow='on'] [data-hud-scroll-panel-body]::-webkit-scrollbar-thumb:active {
  background: linear-gradient(
    135deg,
    transparent 3px,
    color-mix(in srgb, var(--accent) 85%, var(--thumb-hover-mix, #ffffff)) 3px,
    color-mix(in srgb, var(--accent) 85%, var(--thumb-hover-mix, #ffffff)) calc(100% - 3px),
    transparent calc(100% - 3px)
  );
  box-shadow: 0 0 8px var(--glow-color);
}

:root[data-hud-palette='day'][data-hud-glow='on']
  [data-hud-scroll-panel-body]::-webkit-scrollbar-thumb:hover,
:root[data-hud-palette='day'][data-hud-glow='on']
  [data-hud-scroll-panel-body]::-webkit-scrollbar-thumb:active {
  box-shadow: none;
}

/* ---- Chamfer helper ---------------------------------------------------- */

[data-hud-chamfer] {
  clip-path: var(--hud-chamfer-polygon);
}

[data-hud-chamfer][data-size='sm'] {
  --hud-chamfer: var(--hud-chamfer-sm);
}

[data-hud-chamfer][data-size='lg'] {
  --hud-chamfer: var(--hud-chamfer-lg);
}

/* ---- Reduced motion ---------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  [data-hud-scroll-panel-body] {
    scroll-behavior: auto !important;
  }
  [data-hud-dialog],
  [data-hud-dialog-overlay],
  [data-hud-tab],
  [data-hud-toggle],
  [data-hud-meter-fill] {
    transition: none !important;
  }
}

:root[data-hud-motion='off'] [data-hud-dialog],
:root[data-hud-motion='off'] [data-hud-dialog-overlay],
:root[data-hud-motion='off'] [data-hud-tab],
:root[data-hud-motion='off'] [data-hud-toggle],
:root[data-hud-motion='off'] [data-hud-meter-fill] {
  transition: none !important;
}
